diff:
--- old/src/coupled_lammps_main.cpp
+++ new/src/coupled_lammps_main.cpp
@@ -8,4 +8,4 @@
 #include <iostream>
 using namespace LAMMPS_NS;
 static Fix* make_drag(LAMMPS*lmp,int n,char**a){return new FixFrozenFlowDrag(lmp,n,a);}
-int main(int argc,char**argv){MPI_Init(&argc,&argv);try{auto*lmp=new LAMMPS(argc,argv,MPI_COMM_WORLD);(*lmp->modify->fix_map)["frozen/flow/drag"]=&make_drag;lmp->input->file();delete lmp;MPI_Finalize();return 0;}catch(std::exception const&e){std::cerr<<"Coupling adapter error: "<<e.what()<<std::endl;MPI_Abort(MPI_COMM_WORLD,1);return 1;}}
+int main(int argc,char**argv){MPI_Init(&argc,&argv);try{auto*lmp=new LAMMPS(argc,argv,MPI_COMM_WORLD);Modify::fix_styles().set_plugin("frozen/flow/drag", &make_drag);lmp->input->file();delete lmp;MPI_Finalize();return 0;}catch(std::exception const&e){std::cerr<<"Coupling adapter error: "<<e.what()<<std::endl;MPI_Abort(MPI_COMM_WORLD,1);return 1;}}

--- old/src/passive_main.cpp
+++ new/src/passive_main.cpp
@@ -7,4 +7,4 @@
 #include <iostream>
 using namespace LAMMPS_NS;
 static Fix*factory(LAMMPS*l,int n,char**a){return new FixPassiveFlow(l,n,a);}
-int main(int argc,char**argv){MPI_Init(&argc,&argv);try{auto*l=new LAMMPS(argc,argv,MPI_COMM_WORLD);(*l->modify->fix_map)["sonovue/passive/flow"]=&factory;l->input->file();delete l;}catch(std::exception const&e){std::cerr<<e.what()<<std::endl;MPI_Abort(MPI_COMM_WORLD,1);}MPI_Finalize();}
+int main(int argc,char**argv){MPI_Init(&argc,&argv);try{auto*l=new LAMMPS(argc,argv,MPI_COMM_WORLD);Modify::fix_styles().set_plugin("sonovue/passive/flow", &factory);l->input->file();delete l;}catch(std::exception const&e){std::cerr<<e.what()<<std::endl;MPI_Abort(MPI_COMM_WORLD,1);}MPI_Finalize();}
